value.output:
let (Some(lo), Some(hi)) = (lowest_bit(t), highest_bit(t)) else {
    return Ok(());
};
let term_low = lsb + lo as i128;
let term_high = lsb + hi as i128;
let (new_low, new_high) = if self.empty {
    (term_low, term_high)
} else {
    (self.anchor.min(term_low), self.high.max(term_high))
};
let span = new_high - new_low + 1;
if span > SPAN_LIMIT_BITS {
    return Err(SumRefusal::Span);
}
if self.empty {
    self.anchor = new_low;
    self.used = 0;
    self.empty = false;
} else if new_low < self.anchor {
    let shift = (self.anchor - new_low) as usize;
    self.shift_up(shift);
    self.anchor = new_low;
}
self.high = new_high;
self.work.max_span_bits = self.work.max_span_bits.max(span as u64);
// The term with its low zero bits removed (bits above `hi` are zero, so
// each window is exact), added at bit offset (term_low - anchor) >= 0.
let limbs = (hi - lo + 1).div_ceil(64);
let mut trimmed = [0u64; TERM_LIMBS];
for (k, limb) in trimmed.iter_mut().enumerate().take(limbs) {
    *limb = window(t, lo + 64 * k);
}
let offset = (term_low - self.anchor) as usize;
let word = offset / 64;
let bit = (offset % 64) as u32;
let target = if negative {
    &mut self.negative
} else {
    &mut self.positive
};
let mut carry = 0u64;
let mut index = word;
for k in 0..=limbs {
    let current = if k < limbs { trimmed[k] } else { 0 };
    let previous = if k == 0 { 0 } else { trimmed[k - 1] };
    let part = if bit == 0 {
        current
    } else {
        (current << bit) | (previous >> (64 - bit))
    };
    if index >= SUM_LIMBS {
        // Unreachable under the span check (RETURN §5 item 3). Were it
        // reached, a bit that does not fit is refused rather than
        // dropped (RV19-N4); the sum is then unusable, and every
        // caller ends its attempt on `Span`.
        if part != 0 || carry != 0 || trimmed[k.min(limbs)..limbs].iter().any(|&w| w != 0) {
            return Err(SumRefusal::Span);
        }
        break;
    }
    let (s1, c1) = target[index].overflowing_add(part);
    let (s2, c2) = s1.overflowing_add(carry);
    target[index] = s2;
    carry = u64::from(c1) + u64::from(c2);
    index += 1;
}
while carry != 0 {
    debug_assert!(index < SUM_LIMBS, "carry headroom exceeded");
    let (s, c) = target[index].overflowing_add(carry);
    target[index] = s;

// These are standalone algebra paths; no full-case price is inferred.
fn ledger_h_route(
    guard: StageGuard,
    b: f64,
) -> (Result<Option<f64>, AttemptStop>, CertificateMeter) {
    let mut m = CertificateMeter::new(guard);
    let mut r = report(256);
    r.w_plus[0] = Some(w(f64::from_bits(1)));
    let result = (|| {
        let h = publication_h(0, &meta(Kind::Translation), 1.0, &w(0.0), &r, &mut m)?;
        let value = row(
            1.0,
            RowClass::AbsoluteVerified {
                bound_bits: b.to_bits(),
            },
        );
        if publication_predicate(&h, &value, b * pow2(64), &mut m)?.is_some() {
            return Ok(None);
        }
        m.round_up(&h).map(Some)
    })();
    (result, m)
}

fn sum_tuple(s: SumWork) -> (u64, u64, u64, u64) {
    (s.term_limbs, s.shift_limbs, s.net_limbs, s.rounded_limbs)
}

#[test]
fn pc40_independent_absolute_work_ledgers_success_and_numeric_rejection() {
    let (result, m) = ledger_h_route(StageGuard::unlimited(), 2.0);
    assert_eq!(result, Ok(Some(f64::from_bits(1.0f64.to_bits() + 1))));
    assert_eq!(m.total(), 18_103); // H44 + predicate115 + RU17_944.
    assert_eq!(sum_tuple(m.sums), (250, 188, 138, 21));
    assert_eq!(lme(&m.ctx), 17_506);
    assert_eq!(m.sums.max_span_bits, 1075);
    let (result, m) = ledger_h_route(StageGuard::unlimited(), 1.0);
    assert_eq!(result, Ok(None));
    assert_eq!(m.total(), 159); // Rejection precedes RU, not an omitted radius.
    let mut m = meter();
    assert_eq!(
        m.row_bound(f64::from_bits(1), f64::from_bits(1))
            .unwrap()
            .to_bits(),
        3
    );
    assert_eq!(m.total(), 17_563);
    assert_eq!(sum_tuple(m.sums), (32, 6, 15, 4));
    assert_eq!(lme(&m.ctx), 17_506);
    assert_eq!(m.sums.max_span_bits, 2);
}

